const GRAY={1:['0','1'],2:['00','01','11','10']},COLORS=['#e49a62','#73b7bd','#ac91c7','#d0b84e','#d8757e','#6eb181','#568ec2','#df7eb7'];
let n=4,values=Array(16).fill('0'),outputForm='sop',lastGroups=[],groupsVisible=true;
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],variables=()=>['A','B','C','D','E'].slice(0,n),bits=i=>i.toString(2).padStart(n,'0'),cycle=v=>v==='0'?'1':v==='1'?'X':'0',ids=v=>values.map((x,i)=>x===v?i:null).filter(i=>i!==null);
function dims(){return n===2?[2,2]:n===3?[2,4]:[4,4]}
function indexAt(r,c,plane=0){const [rows,cols]=dims(),core=GRAY[Math.log2(rows)][r]+GRAY[Math.log2(cols)][c];return parseInt((n===5?plane:'')+core,2)}
function oneMap(plane=0){const [rows,cols]=dims(),rn=Math.log2(rows),labels=variables().slice(n===5?1:0);let h=`<div class="axis corner">${labels.slice(0,rn).join('')} ╲ ${labels.slice(rn).join('')}</div>`;for(let c=0;c<cols;c++)h+=`<div class="axis">${GRAY[Math.log2(cols)][c]}</div>`;for(let r=0;r<rows;r++){h+=`<div class="axis">${GRAY[Math.log2(rows)][r]}</div>`;for(let c=0;c<cols;c++){let i=indexAt(r,c,plane);h+=`<button class="cell" data-i="${i}" data-v="${values[i]}">${values[i]}<small>m${i}</small></button>`}}return `<div class="map-block">${n===5?`<b class="plane-label">A = ${plane}</b>`:''}<div class="kmap" style="--rows:${rows};--cols:${cols}">${h}</div></div>`}
function renderMap(grouped=false){$('#mapWrap').innerHTML=n===5?oneMap(0)+oneMap(1):oneMap();$$('.cell').forEach(b=>b.onclick=()=>{values[+b.dataset.i]=cycle(values[+b.dataset.i]);renderInputs();hideResults()});if(grouped&&groupsVisible)paintGroups()}
function renderTruthEditor(){let h='<table><thead><tr><th>#</th>'+variables().map(v=>`<th>${v}</th>`).join('')+'<th>Salida</th></tr></thead><tbody>';values.forEach((v,i)=>h+=`<tr><td>m${i}</td>${bits(i).split('').map(x=>`<td>${x}</td>`).join('')}<td><button class="truth-output" data-i="${i}" data-v="${v}">${v}</button></td></tr>`);$('#truthEditor').innerHTML=h+'</tbody></table>';$$('.truth-output').forEach(b=>b.onclick=()=>{values[+b.dataset.i]=cycle(values[+b.dataset.i]);renderInputs();hideResults()})}
function syncLists(){$('#mintermInput').value=ids('1').join(', ');$('#maxtermInput').value=ids('0').join(', ');$('#minDcInput').value=$('#maxDcInput').value=ids('X').join(', ')}
function renderInputs(){renderMap();renderTruthEditor();syncLists()}
function parseList(s){return [...new Set(s.split(/[ ,;]+/).filter(Boolean).map(Number).filter(x=>Number.isInteger(x)&&x>=0&&x<2**n))]}
function applyList(kind){const main=parseList($(kind==='min'?'#mintermInput':'#maxtermInput').value),dc=parseList($(kind==='min'?'#minDcInput':'#maxDcInput').value);values=Array(2**n).fill(kind==='min'?'0':'1');main.forEach(i=>values[i]=kind==='min'?'1':'0');dc.forEach(i=>values[i]='X');renderInputs();hideResults();setMode('map')}
function tokenize(e){let s=e.toUpperCase().replace(/\s+/g,'').replace(/[·.]/g,'*').replace(/∨/g,'+').replace(/¬/g,'!'),a=[];for(const c of s){if(/[A-E01()+*!']/.test(c))a.push(c);else throw Error(`Símbolo no reconocido: ${c}`)}return a}
function evalExpr(expr,assignment){let t=tokenize(expr),p=0;const primary=()=>{let v;if(t[p]==='!'){p++;v=!primary()}else if(t[p]==='('){p++;v=or();if(t[p++]!==')')throw Error('Falta cerrar un paréntesis')}else if(/[A-E01]/.test(t[p]||'')){let x=t[p++];if(/[A-E]/.test(x)&&!variables().includes(x))throw Error(`${x} no existe en un mapa de ${n} variables`);v=x==='1'?true:x==='0'?false:assignment[variables().indexOf(x)]}else throw Error('Se esperaba una variable');while(t[p]==="'"){p++;v=!v}return v},and=()=>{let v=primary();while(p<t.length&&t[p]!==')'&&t[p]!=='+'){if(t[p]==='*')p++;let right=primary();v=v&&right}return v},or=()=>{let v=and();while(t[p]==='+'){p++;let right=and();v=v||right}return v};let result=or();if(p<t.length)throw Error('Revisa la expresión cerca de '+t[p]);return result}
function applyExpression(){try{let e=$('#expressionInput').value.trim();if(!e)throw Error('Escribe una expresión.');values=Array.from({length:2**n},(_,i)=>evalExpr(e,bits(i).split('').map(x=>x==='1'))?'1':'0');$('#expressionError').textContent='';renderInputs();hideResults();setMode('map')}catch(e){$('#expressionError').textContent=e.message}}
function combine(a,b){let d=0,o='';for(let i=0;i<a.length;i++){if(a[i]!==b[i]){if(a[i]==='-'||b[i]==='-')return null;d++;o+='-'}else o+=a[i]}return d===1?o:null}
function primes(on,dc=[]){let terms=[...new Set([...on,...dc])].map(i=>({p:bits(i),covers:new Set([i])})),all=[];while(terms.length){let used=new Set(),next=new Map();for(let i=0;i<terms.length;i++)for(let j=i+1;j<terms.length;j++){let p=combine(terms[i].p,terms[j].p);if(p){used.add(i);used.add(j);let cv=new Set([...terms[i].covers,...terms[j].covers]);if(next.has(p))cv=new Set([...next.get(p).covers,...cv]);next.set(p,{p,covers:cv})}}terms.forEach((t,i)=>{if(!used.has(i)&&[...t.covers].some(x=>on.includes(x)))all.push(t)});terms=[...next.values()]}return [...new Map(all.map(x=>[x.p,x])).values()]}
function chooseCover(on,ps){if(!on.length)return[];let essential=[],remaining=[...on];ps.forEach(p=>{if([...p.covers].some(x=>on.includes(x)&&ps.filter(q=>q.covers.has(x)).length===1)&&!essential.includes(p))essential.push(p)});remaining=remaining.filter(x=>!essential.some(p=>p.covers.has(x)));if(!remaining.length)return essential;let cs=ps.filter(p=>!essential.includes(p)),best=null,max=1<<Math.min(cs.length,20);for(let mask=1;mask<max;mask++){let chosen=[],covered=new Set(),lits=0;for(let i=0;i<cs.length;i++)if(mask>>i&1){chosen.push(cs[i]);lits+=cs[i].p.replaceAll('-','').length;cs[i].covers.forEach(x=>covered.add(x))}if(remaining.every(x=>covered.has(x))&&(!best||chosen.length<best.chosen.length||chosen.length===best.chosen.length&&lits<best.lits))best={chosen,lits}}return [...essential,...(best?.chosen||cs)]}
function term(p,pos=false){let out=[];p.split('').forEach((b,i)=>{if(b==='-')return;let v=variables()[i];out.push(pos?(b==='0'?v:`${v}'`):(b==='1'?v:`${v}'`))});return pos?`(${out.join(' + ')})`:out.join('')||'1'}
function solveSet(target,pos=false){const dc=ids('X');if(!target.length)return {selected:[],text:pos?'1':'0'};if(target.length+dc.length===2**n)return {selected:[],text:pos?'0':'1'};let selected=chooseCover(target,primes(target,dc));return {selected,text:selected.map(x=>term(x.p,pos)).join(pos?' · ':' + ')}}
function solve(){const ones=ids('1'),zeros=ids('0'),dc=ids('X'),sop=solveSet(ones),pos=solveSet(zeros,true),chosen=outputForm==='sop'?sop:pos;lastGroups=chosen.selected;$('#sopResult').textContent=sop.text;$('#posResult').textContent=pos.text;$('#mainResult').textContent=chosen.text;$('#answerLabel').textContent=`Resultado mínimo · ${outputForm.toUpperCase()}`;$('#canonicalSop').textContent=ones.length?`Σm(${ones.join(', ')}) = ${ones.map(i=>term(bits(i))).join(' + ')}`:'Σm(∅)';$('#canonicalPos').textContent=zeros.length?`ΠM(${zeros.join(', ')}) = ${zeros.map(i=>term(bits(i),true)).join(' · ')}`:'ΠM(∅)';$('#canonicalDc').textContent=dc.length?`d(${dc.join(', ')})`:'Sin condiciones X';$('#readResult').textContent=`Se agrupan ${outputForm==='sop'?'los unos':'los ceros'} en ${lastGroups.length} ${lastGroups.length===1?'grupo':'grupos'} mínimos.`;renderGroups();renderTruth();renderCircuit(chosen);renderPLC(chosen);$('#whyText').textContent=`En un grupo de 2ᵏ celdas se eliminan k variables. Las que cambian desaparecen y solo quedan las constantes.${dc.length?' Las X se usaron únicamente cuando permitían grupos mayores.':''}`;$('#results').classList.remove('hidden');setTimeout(()=>$('#results').scrollIntoView({behavior:'smooth',block:'start'}),60)}
function renderGroups(){let h='';lastGroups.forEach((g,k)=>{let all=[...g.covers].filter(i=>values[i]!== (outputForm==='sop'?'0':'1')).sort((a,b)=>a-b),constant=g.p.split('').map((b,i)=>b==='-'?'':`${variables()[i]}=${b}`).filter(Boolean);h+=`<div class="group-item"><i class="group-swatch" style="--group:${COLORS[k%COLORS.length]}"></i><div><b>Grupo ${k+1}: ${term(g.p,outputForm==='pos')}</b><br><span>${all.length} celdas: ${all.map(x=>'m'+x).join(', ')}. Constantes: ${constant.join(', ')||'ninguna'}.</span></div></div>`});$('#groupsList').innerHTML=h||'<p class="note">La función es constante; no necesita agrupaciones.</p>';renderMap(true)}
function paintGroups(){lastGroups.forEach((g,k)=>g.covers.forEach(i=>{let el=$(`.cell[data-i="${i}"]`);if(el&&values[i]!== (outputForm==='sop'?'0':'1')){el.classList.add('grouped');el.style.setProperty('--group',COLORS[k%COLORS.length])}}))}
function renderTruth(){let h='<table><thead><tr><th>#</th>'+variables().map(v=>`<th>${v}</th>`).join('')+'<th>F</th></tr></thead><tbody>';values.forEach((v,i)=>h+=`<tr><td>m${i}</td>${bits(i).split('').map(x=>`<td>${x}</td>`).join('')}<td><b>${v}</b></td></tr>`);$('#truthTable').innerHTML=h+'</tbody></table>'}
function renderCircuit(r){let items=r.selected.length?r.selected.map(x=>term(x.p,outputForm==='pos')):['Constante'],h='<svg viewBox="0 0 620 230" role="img">';items.slice(0,6).forEach((t,i)=>{let y=25+i*32;h+=`<text x="10" y="${y+15}">${t}</text><line x1="115" y1="${y+10}" x2="170" y2="${y+10}"/><rect x="170" y="${y-4}" width="85" height="28" rx="14"/><text x="212" y="${y+14}" text-anchor="middle">${outputForm==='sop'?'AND':'OR'}</text><line x1="255" y1="${y+10}" x2="390" y2="115"/>`});h+=`<rect x="390" y="91" width="95" height="48" rx="22"/><text x="437" y="120" text-anchor="middle">${outputForm==='sop'?'OR':'AND'}</text><line x1="485" y1="115" x2="560" y2="115"/><text x="570" y="120">F</text></svg>`;$('#circuitDiagram').innerHTML=h;$('#circuitTitle').textContent=outputForm==='sop'?'Circuito AND–OR / NAND–NAND':'Circuito OR–AND / NOR–NOR';$('#circuitNote').textContent=outputForm==='sop'?'Cada producto entra a una OR final; por De Morgan también puede hacerse solo con NAND.':'Cada suma entra a una AND final; por De Morgan también puede hacerse solo con NOR.'}
function plcLiterals(pattern,pos=false){let a=[];pattern.split('').forEach((bit,i)=>{if(bit==='-')return;let neg=pos?bit==='1':bit==='0';a.push({name:variables()[i],neg})});return a}
function contact(x){return `<span class="contact ${x.neg?'nc':'na'}"><i>${x.neg?'NC':'NA'}</i><b>${x.name}</b></span>`}
function renderPLC(result){
  if(!result.selected.length){$('#ladderDiagram').innerHTML=`<div class="constant-plc">F = ${result.text}</div>`;$('#fbdDiagram').innerHTML=`<div class="constant-plc">Constante ${result.text} → F</div>`;$('#ladderExplain').textContent='La salida es constante; no se necesitan contactos lógicos.';$('#fbdExplain').textContent='Conecta la constante lógica directamente a la salida.';return}
  const groups=result.selected.map(g=>plcLiterals(g.p,outputForm==='pos'));
  let ladder='<div class="rail left-rail"></div><div class="rail right-rail"></div>';
  if(outputForm==='sop'){
    ladder+='<div class="ladder-branches">'+groups.map((g,i)=>`<div class="rung"><span class="wire"></span>${g.map(contact).join('<span class="wire short"></span>')}<span class="wire grow"></span>${i===0?'<span class="coil">( F )</span>':'<span class="join">●</span>'}</div>`).join('')+'</div>';
    $('#ladderExplain').textContent='Cada término es una rama en paralelo; dentro de cada rama los contactos están en serie.';
  }else{
    ladder+='<div class="pos-rung"><span class="wire"></span>'+groups.map(g=>`<div class="parallel-pack">${g.map(x=>`<div>${contact(x)}</div>`).join('')}</div><span class="wire short"></span>`).join('')+'<span class="wire grow"></span><span class="coil">( F )</span></div>';
    $('#ladderExplain').textContent='Cada suma es un grupo de contactos en paralelo; los grupos se conectan en serie.';
  }
  $('#ladderDiagram').innerHTML=ladder;
  const inner=outputForm==='sop'?'&':'≥1',outer=outputForm==='sop'?'≥1':'&';
  let fbd='<div class="fbd-flow"><div class="fbd-terms">'+groups.map((g,i)=>`<div class="fbd-term"><div class="fbd-inputs">${g.map(x=>`<span>${x.neg?'○ ':''}${x.name}</span>`).join('')}</div><div class="logic-block"><b>${inner}</b><small>T${i+1}</small></div></div>`).join('')+'</div><span class="flow-arrow">→</span><div class="logic-block final"><b>'+outer+'</b><small>F</small></div><span class="flow-arrow">→ F</span></div>';
  $('#fbdDiagram').innerHTML=fbd;$('#fbdExplain').textContent=`${inner==='&'?'Cada producto entra en un bloque AND.':'Cada suma entra en un bloque OR.'} Las entradas con ○ están negadas; las salidas intermedias llegan al bloque ${outer==='&'?'AND':'OR'} final.`
}
