$$('#modeTabs button').forEach(b=>b.onclick=()=>setMode(b.dataset.mode));$$('#varPicker button').forEach(b=>b.onclick=()=>setN(+b.dataset.n));$$('#formPicker button').forEach(b=>b.onclick=()=>{outputForm=b.dataset.form;$$('#formPicker button').forEach(x=>x.classList.toggle('selected',x===b));if(!$('#results').classList.contains('hidden'))solve()});
