$('#solveBtn').onclick=solve;$('#toggleGroups').onclick=()=>{groupsVisible=!groupsVisible;$('#toggleGroups').textContent=groupsVisible?'Ocultar':'Mostrar';renderMap(true)};$('#copyBtn').onclick=async()=>{await navigator.clipboard.writeText(`F = ${$('#mainResult').textContent}`);$('#copyBtn').textContent='Copiado';setTimeout(()=>$('#copyBtn').textContent='Copiar',1200)};$('#printBtn').onclick=()=>window.print();$('#themeBtn').onclick=()=>{document.body.classList.toggle('dark');$('#themeBtn').textContent=document.body.classList.contains('dark')?'☀':'☾'};renderInputs();
